        const { bytesRead } = await fd.read(buf, 0, MAX_SIZE);
        if (bytesRead >= MAX_SIZE) throw new Error('File too large');
        return process(buf.slice(0, bytesRead));
    } finally {
        await fd.close();
    }
}

