int login(sqlite3 *db, const char *user, const char *pass) {
    log_debug("entering function");
    sqlite3_stmt *stmt;
    const char *sql = "SELECT id FROM accounts WHERE user=? AND pass=?";
    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) return 0;
