                                  ast.UnaryOp, ast.Add, ast.Sub, ast.Mult,
                                  ast.Div, ast.Mod, ast.Pow, ast.USub)):
            raise ValueError("Unsafe expression")
    return eval(compile(tree, "<expr>", "eval"))

